let pulse = {};
try {
  const pulseRaw = (($('Leer repo pulse').first().json.stdout) || '{}').trim();
  pulse = JSON.parse(pulseRaw) || {};
} catch (e) {
  pulse = {};
}
let docsHygiene = {};
try {
  const docsRaw = (($('Leer docs hygiene').first().json.stdout) || '{}').trim();
  docsHygiene = JSON.parse(docsRaw) || {};
} catch (e) {
  docsHygiene = {};
}
const raw = ($input.first().json.stdout || '').trim();
let s;
try { s = JSON.parse(raw.split('\n').pop()); } catch (e) { s = { ok: false, error: 'parse' }; }
let text = s.ok ? s.text : ('Reporte Arthur - ERROR: ' + (s.error || 'desconocido'));
if (s.ok && pulse && typeof pulse.totalCommits === 'number') {
  const topLanes = (pulse.byLane || []).slice(0, 5).map((l) => `${l.lane} (${l.commits})`).join(', ');
  const stale = (pulse.staleLanes || []).slice(0, 5).map((l) => `${l.lane}${l.daysSinceLastCommit != null ? ' (' + l.daysSinceLastCommit + 'd)' : ' (sin historial)'}`);
  const lines = [`Repo (ultimas ${pulse.lookbackHours || '?'}h): ${pulse.totalCommits} commits.`];
  if (topLanes) lines.push(`Carriles activos: ${topLanes}`);
  if (stale.length) lines.push(`Sin actividad: ${stale.join(', ')}`);
  text = text + '\n\n' + lines.join('\n');
}
if (s.ok && docsHygiene && docsHygiene.totals) {
  const t = docsHygiene.totals;
  const dLines = [`Docs (limpieza diaria): ${t.identicalDeleted} auto-limpiados, ${t.divergent} divergentes, ${t.newInRoot} nuevos en raiz.`];
  const topDiv = (docsHygiene.divergentFindings || []).slice(0, 5).map((f) => `  - ${f.relPath} vs ${(f.twins && f.twins[0] && f.twins[0].relPath) || '?'}`);
  if (topDiv.length) { dLines.push('Divergentes (fusion manual):'); dLines.push(...topDiv); }
  if ((docsHygiene.divergentFindings || []).length > 5) dLines.push(`  ...+${docsHygiene.divergentFindings.length - 5} mas`);
  const topNew = (docsHygiene.newInRootFindings || []).slice(0, 5).map((f) => `  - ${f.relPath}`);
  if (topNew.length) { dLines.push('Nuevos en raiz (mover a docs/):'); dLines.push(...topNew); }
  if ((docsHygiene.newInRootFindings || []).length > 5) dLines.push(`  ...+${docsHygiene.newInRootFindings.length - 5} mas`);
  text = text + '\n\n' + dLines.join('\n');
}
return [{ json: { text: text } }];
